import React, { useState, useEffect } from 'react';
import './App.css';
import Clue from './components/Clue';  // Component for each clue

function App() {
  const [clues, setClues] = useState([]);
  const [teamName, setTeamName] = useState('');
  const [isRegistered, setIsRegistered] = useState(false);

  // Sample hardcoded clues (can later fetch from API)
  useEffect(() => {
    setClues([
      {
        id: 1,
        story: 'She never left her desk. But there was one tool she trusted above all. It typed no code but held every thought.',
        answer: 'notebook',
        image: '/assets/images/desk.jpg',
      },
      {
        id: 2,
        story: 'The voice of the forgotten echoed into this device. It heard secrets not meant for any ear.',
        answer: 'microphone',
        image: '/assets/images/microphone.jpg',
      },
      // Add more clues here
    ]);
  }, []);

  const handleRegistration = () => {
    if (teamName) {
      setIsRegistered(true);
    }
  };

  return (
    <div className="App">
      <div className="register-section">
        {!isRegistered ? (
          <div>
            <h1>Register Your Team</h1>
            <input
              type="text"
              value={teamName}
              onChange={(e) => setTeamName(e.target.value)}
              placeholder="Enter Team Name"
            />
            <button onClick={handleRegistration}>Register</button>
          </div>
        ) : (
          <div>
            <h1>Welcome {teamName}, let the mystery begin!</h1>
            {clues.map((clue) => (
              <Clue key={clue.id} clue={clue} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
